steps.solution:
books = [
    {"title": "Dune", "author": "Frank Herbert", "year": 1965},
    {"title": "Emma", "author": "Jane Austen", "year": 1815},
    {"title": "Persuasion", "author": "Jane Austen", "year": 1817},
    {"title": "Neuromancer", "author": "William Gibson", "year": 1984},
]
print(len(books))

titles = [b["title"] for b in books]
classics = [b["title"] for b in books if b["year"] < 1900]
print(titles)
print(classics)

by_year = sorted(books, key=lambda b: b["year"])
print(by_year[-1]["title"])

authors = {b["author"] for b in books}
print(", ".join(sorted(authors)))

per_author = {}
for b in books:
    per_author[b["author"]] = per_author.get(b["author"], 0) + 1
print(per_author)

pairs = [(b["title"], b["year"]) for b in books]
for i, (title, year) in enumerate(pairs, start=1):
    print(f"{i}. {title} ({year})")


class Book:
    def __init__(self, title, author, year):
        self.title = title
        self.author = author
        self.year = year
        self.available = True

    def check_out(self):
        if not self.available:
            return False
        self.available = False
        return True

    def give_back(self):
        self.available = True

    def __str__(self):
        return f"{self.title} by {self.author} ({self.year})"


dune = Book("Dune", "Frank Herbert", 1965)
print(dune.title)
print(dune.check_out())
print(dune.check_out())
print(dune)


class Library:
    def __init__(self):
        self.books = []

    def add(self, book):
        self.books.append(book)

    def by_author(self, author):
        return [b for b in self.books if b.author == author]


library = Library()
for b in books:
    library.add(Book(b["title"], b["author"], b["year"]))
