def test_grades():
    assert [grade(s) for s in (95, 90, 85, 70, 69, 0)] == ["A", "A", "B", "C", "F", "F"]


def test_grade_range():
    for bad in (-1, 101):
        try:
            grade(bad)
        except ValueError:
            continue
        assert False, f"{bad} should raise"


def grade(score):
    if not 0 <= score <= 100:
        raise ValueError("score must be 0-100")
    if score >= 90:
        return "A"
    if score >= 80:
        return "B"
    if score >= 70:
        return "C"
    return "F"


print(run_tests([test_withdraw_ok, test_withdraw_exact, test_to_int_bad, test_overdraw_raises, test_grades, test_grade_range]))

