function receipt(order) {
  const lines = order.map(i => `${i.name} x${i.qty} = ${i.price * i.qty}`);
  const total = order.reduce((s, i) => s + i.price * i.qty, 0);
  lines.push(`Total: ${total}`);
  return lines.join("\n");
}
