            break
    return steps


def count_binary(items, target):
    lo, hi, steps = 0, len(items) - 1, 0
    while lo <= hi:
        steps += 1
        mid = (lo + hi) // 2
        if items[mid] == target:
            break
        if items[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return steps


big = list(range(1000))
print(count_linear(big, 999), count_binary(big, 999))


def factorial(n):
    if n == 0:
        return 1
    return n * factorial(n - 1)


def total(items):
    if not items:
        return 0
    return items[0] + total(items[1:])


print(factorial(5))


def selection_sort(items):
    a = items[:]
    for i in range(len(a)):
        smallest = i
        for j in range(i + 1, len(a)):
            if a[j] < a[smallest]:
                smallest = j
        a[i], a[smallest] = a[smallest], a[i]
    return a


print(selection_sort([5, 2, 9, 1, 5, 6]))


def merge(a, b):
    out, i, j = [], 0, 0
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            out.append(a[i])
            i += 1
        else:
            out.append(b[j])
            j += 1
    return out + a[i:] + b[j:]


print(merge([1, 4, 9], [2, 3, 10]))


def merge_sort(items):
    if len(items) <= 1:
        return items[:]
    mid = len(items) // 2
    return merge(merge_sort(items[:mid]), merge_sort(items[mid:]))


print(merge_sort([38, 27, 43, 3, 9, 82, 10]))


def fib(n, memo=None):
    if memo is None:
        memo = {}
    if n < 2:
        return n
    if n not in memo:
        memo[n] = fib(n - 1, memo) + fib(n - 2, memo)
    return memo[n]


print(fib(80))


from collections import deque


def shortest_path(maze):
    rows, cols = len(maze), len(maze[0])
    start = next((r, c) for r in range(rows) for c in range(cols) if maze[r][c] == "S")
    seen = {start}
    queue = deque([(start, 0)])
    while queue:
        (r, c), dist = queue.popleft()
        if maze[r][c] == "E":
            return dist
        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= nr < rows and 0 <= nc < cols and maze[nr][nc] != "#" and (nr, nc) not in seen:
                seen.add((nr, nc))
                queue.append(((nr, nc), dist + 1))
    return -1


maze = [
    "S.#.....",
    ".##.###.",
    "....#...",
    "##.#..#E",
]
print(shortest_path(maze))


import time

data = [(i * 7919) % 2003 for i in range(2000)]
start = time.perf_counter()
slow = selection_sort(data)
slow_time = time.perf_counter() - start
start = time.perf_counter()
fast = merge_sort(data)
fast_time = time.perf_counter() - start
assert slow == fast == sorted(data)
winner = "merge sort" if fast_time < slow_time else "selection sort"
print(f"selection sort: {slow_time:.3f}s, merge sort: {fast_time:.3f}s")
print(f"Faster: {winner}")
